def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]

    for r, c in sixes:
        out[r][c] = 0

    # The T-shaped marker calls for a left/right reflection.
    row_counts = {}
    for r, c in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
    bar_row = max(row_counts, key=row_counts.get)

    if len(sixes) == 5:
        bar_cols = [c for r, c in sixes if r == bar_row]
        center = (min(bar_cols) + max(bar_cols)) // 2
        stem_rows = [r for r, c in sixes if c == center and r != bar_row]
        stem_is_below = sum(r > bar_row for r in stem_rows) > sum(r < bar_row for r in stem_rows)

        if stem_is_below:  # reflect to the right
            edge = max(c for r, c in fours)
            for r, c in fours:
                nc = 2 * edge + 1 - c
                if nc < w:
                    out[r][nc] = 4
        else:  # reflect to the left
            edge = min(c for r, c in fours)
            for r, c in fours:
                nc = 2 * edge - 1 - c
                if nc >= 0:
                    out[r][nc] = 4
    else:
        # Otherwise reflect vertically, toward the side with more room.
        top = min(r for r, c in fours)
        bottom = max(r for r, c in fours)
        up_room = top
        down_room = h - 1 - bottom

        if down_room > up_room:
            for r, c in fours:
                nr = 2 * bottom + 1 - r
                if nr < h:
                    out[nr][c] = 4
        else:
            for r, c in fours:
                nr = 2 * top - 1 - r
                if nr >= 0:
                    out[nr][c] = 4

    return out
